needle:
if (typeof input !== 'string') {
  throw new TypeError('Expected a string');
}

guard:
// Local GHSA-fc5q-39xc-vjpf mitigation: reject repeated extglobs before regex generation.
// Deliberately conservative: this build does not support +(...) or *(...).
if (/[+*]\(/.test(input)) {
  throw new SyntaxError('Repeated extglobs are disabled by the build security policy');
}
